import{_ as s,c as a,a as e,o as t}from"./app-CuISi-j2.js";const p={};function o(c,n){return t(),a("div",null,n[0]||(n[0]=[e(`<h1 id="kafka" tabindex="-1"><a class="header-anchor" href="#kafka"><span>Kafka</span></a></h1><p>FluxaORM provides first-class support for Apache Kafka as a data pool type. Under the hood it uses <a href="https://github.com/twmb/franz-go" target="_blank" rel="noopener noreferrer">franz-go</a>, a high-performance pure-Go Kafka client.</p><h2 id="pool-registration" tabindex="-1"><a class="header-anchor" href="#pool-registration"><span>Pool Registration</span></a></h2><p>Register a Kafka pool using the <code>RegisterKafka</code> method:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">import</span> <span class="token string">&quot;github.com/latolukasz/fluxaorm/v2&quot;</span></span>
<span class="line"></span>
<span class="line">registry <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewRegistry</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Kafka pool named &quot;events&quot; with default options:</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Pool with custom options:</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;localhost:9093&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaOptions<span class="token punctuation">{</span></span>
<span class="line">    ClientID<span class="token punctuation">:</span>      <span class="token string">&quot;my-service&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    ConsumerGroup<span class="token punctuation">:</span> <span class="token string">&quot;my-group&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    ConsumeTopics<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;payments&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Equivalent YAML configuration:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">events</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> localhost<span class="token punctuation">:</span><span class="token number">9092</span></span>
<span class="line">      <span class="token punctuation">-</span> localhost<span class="token punctuation">:</span><span class="token number">9093</span></span>
<span class="line">    <span class="token key atrule">clientID</span><span class="token punctuation">:</span> my<span class="token punctuation">-</span>service</span>
<span class="line">    <span class="token key atrule">consumerGroup</span><span class="token punctuation">:</span> my<span class="token punctuation">-</span>group</span>
<span class="line">    <span class="token key atrule">consumeTopics</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> orders</span>
<span class="line">      <span class="token punctuation">-</span> payments</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="kafkaoptions" tabindex="-1"><a class="header-anchor" href="#kafkaoptions"><span>KafkaOptions</span></a></h2><p>The <code>KafkaOptions</code> struct lets you configure the Kafka client:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> KafkaOptions <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    ClientID           <span class="token builtin">string</span></span>
<span class="line">    ConsumerGroup      <span class="token builtin">string</span></span>
<span class="line">    ConsumeTopics      <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span></span>
<span class="line">    RequiredAcks       <span class="token builtin">int</span></span>
<span class="line">    ProducerLinger     time<span class="token punctuation">.</span>Duration</span>
<span class="line">    MaxBufferedRecords <span class="token builtin">int</span></span>
<span class="line">    SessionTimeout     time<span class="token punctuation">.</span>Duration</span>
<span class="line">    RebalanceTimeout   time<span class="token punctuation">.</span>Duration</span>
<span class="line">    FetchMaxBytes      <span class="token builtin">int32</span></span>
<span class="line">    AutoCommitInterval time<span class="token punctuation">.</span>Duration</span>
<span class="line">    SASL               <span class="token operator">*</span>KafkaSASLConfig</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ClientID</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Client identifier sent to the broker</td></tr><tr><td><code>ConsumerGroup</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Consumer group ID for group consumption</td></tr><tr><td><code>ConsumeTopics</code></td><td><code>[]string</code></td><td><code>nil</code></td><td>Topics to consume from</td></tr><tr><td><code>RequiredAcks</code></td><td><code>int</code></td><td><code>-1</code></td><td>Broker acknowledgment level: <code>0</code> = none, <code>1</code> = leader only, <code>-1</code> = all in-sync replicas</td></tr><tr><td><code>ProducerLinger</code></td><td><code>time.Duration</code></td><td><code>0</code></td><td>How long to wait before flushing a produce batch</td></tr><tr><td><code>MaxBufferedRecords</code></td><td><code>int</code></td><td><code>0</code></td><td>Maximum number of records buffered in the producer</td></tr><tr><td><code>SessionTimeout</code></td><td><code>time.Duration</code></td><td><code>0</code></td><td>Consumer group session timeout</td></tr><tr><td><code>RebalanceTimeout</code></td><td><code>time.Duration</code></td><td><code>0</code></td><td>Consumer group rebalance timeout</td></tr><tr><td><code>FetchMaxBytes</code></td><td><code>int32</code></td><td><code>0</code></td><td>Maximum bytes per fetch response</td></tr><tr><td><code>AutoCommitInterval</code></td><td><code>time.Duration</code></td><td><code>0</code></td><td>Interval for automatic offset commits; <code>0</code> means manual commit</td></tr><tr><td><code>SASL</code></td><td><code>*KafkaSASLConfig</code></td><td><code>nil</code></td><td>SASL authentication configuration</td></tr></tbody></table><h2 id="config-struct" tabindex="-1"><a class="header-anchor" href="#config-struct"><span>Config Struct</span></a></h2><p>When loading configuration from a file, FluxaORM uses the <code>ConfigKafka</code> struct:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> ConfigKafka <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Brokers            <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span></span>
<span class="line">    ClientID           <span class="token builtin">string</span></span>
<span class="line">    ConsumerGroup      <span class="token builtin">string</span></span>
<span class="line">    ConsumeTopics      <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span></span>
<span class="line">    RequiredAcks       <span class="token builtin">int</span></span>
<span class="line">    ProducerLinger     time<span class="token punctuation">.</span>Duration</span>
<span class="line">    MaxBufferedRecords <span class="token builtin">int</span></span>
<span class="line">    SessionTimeout     time<span class="token punctuation">.</span>Duration</span>
<span class="line">    RebalanceTimeout   time<span class="token punctuation">.</span>Duration</span>
<span class="line">    FetchMaxBytes      <span class="token builtin">int32</span></span>
<span class="line">    AutoCommitInterval time<span class="token punctuation">.</span>Duration</span>
<span class="line">    SASL               <span class="token operator">*</span>KafkaSASLConfig</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="engine-accessor" tabindex="-1"><a class="header-anchor" href="#engine-accessor"><span>Engine Accessor</span></a></h2><p>Once the engine is created, access a Kafka pool via:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">kafka <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>This returns a <code>Kafka</code> interface that exposes the methods described below.</p><h2 id="kafkarecord" tabindex="-1"><a class="header-anchor" href="#kafkarecord"><span>KafkaRecord</span></a></h2><p><code>KafkaRecord</code> represents a single Kafka record (message):</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> KafkaRecord <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Topic     <span class="token builtin">string</span></span>
<span class="line">    Key       <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span></span>
<span class="line">    Value     <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span></span>
<span class="line">    Headers   <span class="token punctuation">[</span><span class="token punctuation">]</span>KafkaRecordHeader</span>
<span class="line">    Partition <span class="token builtin">int32</span></span>
<span class="line">    Offset    <span class="token builtin">int64</span></span>
<span class="line">    Timestamp time<span class="token punctuation">.</span>Time</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="kafkarecordheader" tabindex="-1"><a class="header-anchor" href="#kafkarecordheader"><span>KafkaRecordHeader</span></a></h2><p><code>KafkaRecordHeader</code> represents a key-value header attached to a record:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> KafkaRecordHeader <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Key   <span class="token builtin">string</span></span>
<span class="line">    Value <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="kafkafetches" tabindex="-1"><a class="header-anchor" href="#kafkafetches"><span>KafkaFetches</span></a></h2><p><code>KafkaFetches</code> is returned by <code>PollFetches</code> and provides helper methods for iterating over fetched records:</p><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>Records() []*KafkaRecord</code></td><td>Returns all records from the fetch as a flat slice</td></tr><tr><td><code>EachRecord(func(*KafkaRecord))</code></td><td>Iterates over each record, calling the provided function</td></tr><tr><td><code>EachError(func(string, int32, error))</code></td><td>Iterates over per-partition errors (topic, partition, error)</td></tr><tr><td><code>IsEmpty() bool</code></td><td>Returns <code>true</code> if the fetch contains no records</td></tr></tbody></table><h2 id="producing-records" tabindex="-1"><a class="header-anchor" href="#producing-records"><span>Producing Records</span></a></h2><h3 id="synchronous-produce" tabindex="-1"><a class="header-anchor" href="#synchronous-produce"><span>Synchronous Produce</span></a></h3><p><code>ProduceSync</code> sends one or more records to Kafka and blocks until the broker acknowledges them:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">kafka <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">record <span class="token operator">:=</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaRecord<span class="token punctuation">{</span></span>
<span class="line">    Topic<span class="token punctuation">:</span> <span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    Key<span class="token punctuation">:</span>   <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">&quot;order-123&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Value<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;status&quot;:&quot;created&quot;}\`</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Headers<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>fluxaorm<span class="token punctuation">.</span>KafkaRecordHeader<span class="token punctuation">{</span></span>
<span class="line">        <span class="token punctuation">{</span>Key<span class="token punctuation">:</span> <span class="token string">&quot;source&quot;</span><span class="token punctuation">,</span> Value<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">&quot;api&quot;</span><span class="token punctuation">)</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">err <span class="token operator">:=</span> kafka<span class="token punctuation">.</span><span class="token function">ProduceSync</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> record<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// handle error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="asynchronous-produce" tabindex="-1"><a class="header-anchor" href="#asynchronous-produce"><span>Asynchronous Produce</span></a></h3><p><code>Produce</code> sends a record asynchronously. The call returns immediately and the record is buffered for delivery:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">kafka <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">record <span class="token operator">:=</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaRecord<span class="token punctuation">{</span></span>
<span class="line">    Topic<span class="token punctuation">:</span> <span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    Key<span class="token punctuation">:</span>   <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">&quot;order-456&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Value<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;status&quot;:&quot;shipped&quot;}\`</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">kafka<span class="token punctuation">.</span><span class="token function">Produce</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> record<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="consuming-records" tabindex="-1"><a class="header-anchor" href="#consuming-records"><span>Consuming Records</span></a></h2><h3 id="pollfetches" tabindex="-1"><a class="header-anchor" href="#pollfetches"><span>PollFetches</span></a></h3><p><code>PollFetches</code> polls the broker for new records. It returns a <code>KafkaFetches</code> value:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">kafka <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">fetches <span class="token operator">:=</span> kafka<span class="token punctuation">.</span><span class="token function">PollFetches</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> fetches<span class="token punctuation">.</span><span class="token function">IsEmpty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">fetches<span class="token punctuation">.</span><span class="token function">EachError</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>topic <span class="token builtin">string</span><span class="token punctuation">,</span> partition <span class="token builtin">int32</span><span class="token punctuation">,</span> err <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    log<span class="token punctuation">.</span><span class="token function">Printf</span><span class="token punctuation">(</span><span class="token string">&quot;fetch error topic=%s partition=%d: %v&quot;</span><span class="token punctuation">,</span> topic<span class="token punctuation">,</span> partition<span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">fetches<span class="token punctuation">.</span><span class="token function">EachRecord</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>record <span class="token operator">*</span>fluxaorm<span class="token punctuation">.</span>KafkaRecord<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Printf</span><span class="token punctuation">(</span><span class="token string">&quot;topic=%s key=%s value=%s\\n&quot;</span><span class="token punctuation">,</span> record<span class="token punctuation">.</span>Topic<span class="token punctuation">,</span> record<span class="token punctuation">.</span>Key<span class="token punctuation">,</span> record<span class="token punctuation">.</span>Value<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="commituncommittedoffsets" tabindex="-1"><a class="header-anchor" href="#commituncommittedoffsets"><span>CommitUncommittedOffsets</span></a></h3><p>After processing records, commit the offsets so they are not re-delivered:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">err <span class="token operator">:=</span> kafka<span class="token punctuation">.</span><span class="token function">CommitUncommittedOffsets</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// handle error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>When <code>AutoCommitInterval</code> is set to <code>0</code> (the default), you must call <code>CommitUncommittedOffsets</code> manually after processing each batch. Set a positive <code>AutoCommitInterval</code> to enable automatic periodic commits.</p></div><h2 id="advanced-usage" tabindex="-1"><a class="header-anchor" href="#advanced-usage"><span>Advanced Usage</span></a></h2><p>If you need direct access to the underlying <code>*kgo.Client</code> from franz-go, use <code>GetKgoClient</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">client <span class="token operator">:=</span> kafka<span class="token punctuation">.</span><span class="token function">GetKgoClient</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// use the franz-go client directly for advanced operations</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="sasl-authentication" tabindex="-1"><a class="header-anchor" href="#sasl-authentication"><span>SASL Authentication</span></a></h2><p>To connect to a Kafka cluster that requires SASL authentication, configure the <code>SASL</code> field in <code>KafkaOptions</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;kafka-broker:9093&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;secure-events&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaOptions<span class="token punctuation">{</span></span>
<span class="line">    ClientID<span class="token punctuation">:</span>      <span class="token string">&quot;my-service&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    ConsumerGroup<span class="token punctuation">:</span> <span class="token string">&quot;my-group&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    ConsumeTopics<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    SASL<span class="token punctuation">:</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaSASLConfig<span class="token punctuation">{</span></span>
<span class="line">        Mechanism<span class="token punctuation">:</span> <span class="token string">&quot;SCRAM-SHA-256&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        User<span class="token punctuation">:</span>      <span class="token string">&quot;kafka-user&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        Password<span class="token punctuation">:</span>  <span class="token string">&quot;kafka-password&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>KafkaSASLConfig</code> supports the following mechanisms:</p><table><thead><tr><th>Mechanism</th><th>Description</th></tr></thead><tbody><tr><td><code>PLAIN</code></td><td>Simple username/password authentication (not recommended for production without TLS)</td></tr><tr><td><code>SCRAM-SHA-256</code></td><td>Challenge-response authentication using SHA-256</td></tr><tr><td><code>SCRAM-SHA-512</code></td><td>Challenge-response authentication using SHA-512</td></tr></tbody></table><p>Equivalent YAML:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">secure-events</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> kafka<span class="token punctuation">-</span>broker<span class="token punctuation">:</span><span class="token number">9093</span></span>
<span class="line">    <span class="token key atrule">clientID</span><span class="token punctuation">:</span> my<span class="token punctuation">-</span>service</span>
<span class="line">    <span class="token key atrule">consumerGroup</span><span class="token punctuation">:</span> my<span class="token punctuation">-</span>group</span>
<span class="line">    <span class="token key atrule">consumeTopics</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> orders</span>
<span class="line">    <span class="token key atrule">sasl</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">mechanism</span><span class="token punctuation">:</span> SCRAM<span class="token punctuation">-</span>SHA<span class="token punctuation">-</span><span class="token number">256</span></span>
<span class="line">      <span class="token key atrule">user</span><span class="token punctuation">:</span> kafka<span class="token punctuation">-</span>user</span>
<span class="line">      <span class="token key atrule">password</span><span class="token punctuation">:</span> kafka<span class="token punctuation">-</span>password</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="closing-the-client" tabindex="-1"><a class="header-anchor" href="#closing-the-client"><span>Closing the Client</span></a></h2><p>When you are done using a Kafka pool, call <code>Close</code> to release all resources (connections, goroutines, buffers):</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">kafka<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>If you are using FluxaORM&#39;s engine lifecycle, the engine will close all Kafka clients when it shuts down. You only need to call <code>Close</code> manually if you are managing the Kafka client outside of the engine lifecycle.</p></div>`,56)]))}const l=s(p,[["render",o]]),u=JSON.parse('{"path":"/guide/kafka.html","title":"Kafka","lang":"en-US","frontmatter":{},"git":{"updatedTime":1773756357000,"contributors":[{"name":"Lukasz Lato","username":"","email":"latolukasz@gmail.com","commits":1}],"changelog":[{"hash":"637451bade66fd4bb54ab6a9f2a224e4f444cd65","time":1773756357000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"}]},"filePathRelative":"guide/kafka.md"}');export{l as comp,u as data};
